#define PCI_DB_COUNT 20348

// Explicitly define the header to fix the 'incomplete type' error
struct uacpi_table_header {
	char signature[4];
	uint32_t length;
	uint8_t revision;
	uint8_t checksum;
	char oem_id[6];
	char oem_table_id[8];
	uint32_t oem_revision;
	char asl_compiler_id[4];
	uint32_t asl_compiler_revision;
} __attribute__((packed));

struct mcfg_entry {
	uint64_t base_address;
	uint16_t segment;
	uint8_t bus_start;
	uint8_t bus_end;
	uint32_t reserved;
} __attribute__((packed));

uint32_t pcie_read32(uintptr_t ecam, uint8_t bus, uint8_t dev, uint8_t func,
		     uint16_t offset)
{
	// 1. Calculate the address
	uintptr_t address = ecam + ((uintptr_t)bus << 20) |
			    ((uintptr_t)dev << 15) | ((uintptr_t)func << 12) |
			    (offset & 0xFFF);

	// 2. Perform the memory read
	// Use 'volatile' to prevent the compiler from optimizing out the read
	return *(volatile uint32_t *)address;
}

/**
 * @param base_addr The virtual address where the MCFG PCIe region is mapped.
 * @param bus       0-255
 * @param device    0-31
 * @param function  0-7
 * @param offset    Register offset (0-4095, must be 4-byte aligned)
 * @param value     The 32-bit value to write
 */
void pcie_write32(uintptr_t base_addr, uint8_t bus, uint8_t device,
		  uint8_t function, uint16_t offset, uint32_t value)
{
	// PCIe ECAM Address Calculation:
	// Address = Base + (Bus << 20) | (Device << 15) | (Function << 12) |
	// Offset
	uintptr_t addr = base_addr | ((uintptr_t)bus << 20) |
			 ((uintptr_t)device << 15) |
			 ((uintptr_t)function << 12) | (offset & 0xFFF);

	// Use volatile to ensure the compiler doesn't optimize out the write
	*(volatile uint32_t *)(addr) = value;
}
#define UACPI_SIG_MCFG "MCFG"
void detect_pcie_ecam(void)
{
	uacpi_table tbl;
	uacpi_table_find_by_signature(UACPI_SIG_MCFG, &tbl);

	struct uacpi_table_identifiers ids = {.signature = UACPI_SIG_MCFG};
	if (uacpi_unlikely_error(uacpi_table_find(&ids, &tbl))) {
		uacpi_kernel_log(UACPI_LOG_ERROR, "MCFG not found");
		return;
	}
	for (;;)
		;
	// Now sizeof works because we defined the struct above
	uacpi_size header_offset = sizeof(struct uacpi_table_header) + 8;

	// Use the casted pointer to access 'length'
	struct uacpi_table_header *hdr = (struct uacpi_table_header *)tbl.ptr;

	uacpi_size entries_len = hdr->length - header_offset;
	uacpi_size entry_count = entries_len / sizeof(struct mcfg_entry);
	struct mcfg_entry *entries =
	    (struct mcfg_entry *)((uint8_t *)tbl.ptr + header_offset);

	for (uacpi_size i = 0; i < entry_count; i++) {
		char buf[128];
		uacpi_snprintf(buf, sizeof(buf),
			       "[%q OK %Q] PCIe ECAM Base: %x",
			       entries[i].base_address);
		uacpi_kernel_log(UACPI_LOG_INFO, buf);
	}
}
// returns pointer to BARs if found, NULL otherwise
struct pcie_bars *pcie_find_bars_ecam_class(uint64_t ecam_base, uint8_t class,
					    uint8_t subclass)
{
	static struct pcie_bars bars_result;

	for (int b = 0; b < 256; b++) {
		for (int d = 0; d < 32; d++) {
			uint32_t id = pcie_read32(ecam_base, b, d, 0, 0x00);
			if ((id & 0xFFFF) == 0xFFFF)
				continue;

			uint32_t class_info =
			    pcie_read32(ecam_base, b, d, 0, 0x08);
			if (((class_info >> 24) & 0xFF) == class &&
			    ((class_info >> 16) & 0xFF) == subclass) {

				// 1. Disable the device while we reconfigure
				// BARs
				pcie_write32(ecam_base, b, d, 0, 0x04, 0);

				// 2. Allocate 4KB aligned memory for the
				// Register Space We use 4096 to ensure we stay
				// on a clean page boundary
				void *mmio_space = kmalloc_aligned(4096, 4096);
				if (!mmio_space)
					return 0;

				uint64_t my_addr = (uint64_t)mmio_space;

				// 3. Detect BAR width and write the address
				uint32_t bar_low =
				    pcie_read32(ecam_base, b, d, 0, 0x10);

				// Set the address. We don't need to OR with 0x4
				// because the card's read-only bits will handle
				// the type identification.
				pcie_write32(ecam_base, b, d, 0, 0x10,
					     (uint32_t)my_addr);

				// Check if it's a 64-bit BAR (bit 2 set)
				if ((bar_low >> 2) & 0x1) {
					pcie_write32(ecam_base, b, d, 0, 0x14,
						     (uint32_t)(my_addr >> 32));
				}

				// 4. Enable: Memory Space (0x2) | Bus Mastering
				// (0x4) Bus Mastering is required for the NIC
				// to perform DMA.
				pcie_write32(ecam_base, b, d, 0, 0x04, 0x0006);

				// 5. Store and return
				bars_result.bar[0] = my_addr;
				bars_result.bus = b;
				bars_result.device = d;
				bars_result.function = 0;

				return &bars_result;
			}
		}
	}
	return 0;
}
const char *pci_lookup_name(uint16_t vendor, uint16_t device)
{
	int low = 0;
	int high = PCI_DB_COUNT - 1;

	while (low <= high) {
		int mid = (low + high) / 2;
		const struct pci_ident *entry = &pci_db[mid];

		if (entry->vendor == vendor && entry->device == device)
			return entry->name;

		// Compare vendor first, then device
		if (entry->vendor < vendor ||
		    (entry->vendor == vendor && entry->device < device))
			low = mid + 1;
		else
			high = mid - 1;
	}
	return "Unknown Device";
}
#include <stdint.h>

/* Assembly wrappers for x86 I/O ports */
static inline void outl(uint16_t port, uint32_t val)
{
	asm volatile("outl %0, %1" : : "a"(val), "Nd"(port));
}

static inline uint32_t inl(uint16_t port)
{
	uint32_t ret;
	asm volatile("inl %1, %0" : "=a"(ret) : "Nd"(port));
	return ret;
}

/**
 * Scans all 256 PCI buses, identifies devices,
 * and prints their names using the generated database.
 */
void list_all_pci_devices(void)
{
	kprintf("\n[PCI ENUMERATION]\n");
	kprintf("BDF      VENDOR:DEVICE  BAR0        DESCRIPTION\n");
	kprintf("----------------------------------------------------------\n");

	for (uint32_t bus = 0; bus < 256; bus++) {
		for (uint32_t dev = 0; dev < 32; dev++) {
			for (uint32_t func = 0; func < 8; func++) {
				uint32_t address =
				    (uint32_t)((bus << 16) | (dev << 11) |
					       (func << 8) | 0x80000000);

				outl(0xCF8, address); // Offset 0x00
				uint32_t id_reg = inl(0xCFC);
				uint16_t vendor = (uint16_t)(id_reg & 0xFFFF);
				uint16_t device = (uint16_t)(id_reg >> 16);

				if (vendor == 0xFFFF) {
					if (func == 0)
						break;
					continue;
				}

				// --- NEW: Read BAR1 at Offset 0x14 ---
				outl(0xCF8, address | 0x14);
				uint32_t bar0 = inl(0xCFC);

				const char *name =
				    pci_lookup_name(vendor, device);

				kprintf("%x:%x.%d  %x:%x   %x    %s\n", bus,
					dev, func, vendor, device, bar0, name);

				if (func == 0) {
					outl(0xCF8, address | 0x0C);
					if (!((inl(0xCFC) >> 16) & 0x80))
						break;
				}
			}
		}
	}
}